const rows = $input.all().map(i => i.json);
const free = rows.filter(r => String(r.used || '').trim().toUpperCase() !== 'TRUE' && r.hook && r.quote1);
if (!free.length) throw new Error('Sheet me koi unused carousel row nahi bachi (used != TRUE wali row chahiye)');
return [{ json: { ...free[0] } }];

// Aap yahan apni 3 pasandeeda music files ki IDs aur names daal dein
const musicFiles = [
  { id: '1lcnAuIwiS6f87y4z8TY2_OQzjOpkD0SR', name: 'Song 1.mp3' },
  { id: '1tAD1qqMBk4XkHgl76wCRtAfsvpDAwKTU', name: 'Song 2.mp3' },
  { id: '1Oj0rkvmaaI9GSx3XdOmJTVVjO1EnoesG', name: 'Song 3.mp3' }
];

// Agar list khali ho toh error throw karega
if (!musicFiles.length) {
  throw new Error('Koi music file available nahi hai');
}

// Teeno me se randomly aik file choose karega
const f = musicFiles[Math.floor(Math.random() * musicFiles.length)];

return [{ json: { fileId: f.id, name: f.name } }];

const cfg = $('Config').first().json;
const q = $('Pick Quote').first().json;
const photos = ($('Pexels Search').first().json.photos || []).map(p => p.src.original || p.src.large2x);
if (!photos.length) throw new Error('Pexels se koi photo nahi mili: visual_keyword change karo');
const urls = [0, 1, 2, 3].map(i => photos[i % photos.length]);

function wrap(text, width) {
  const words = String(text || '').trim().split(/\s+/);
  const lines = []; let cur = '';
  for (const w of words) {
    if ((cur + ' ' + w).trim().length > width && cur) { lines.push(cur); cur = w; }
    else cur = (cur + ' ' + w).trim();
  }
  if (cur) lines.push(cur);
  return lines.join('\n');
}
const b64 = s => Buffer.from(s, 'utf8').toString('base64');
const rnd = (a, b) => a + Math.random() * (b - a);
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

// har quote ke shuru aur akhir me " lazmi
const stripQ = s => String(s || '').trim().replace(/^["'\u201C\u201D\u2018\u2019]+|["'\u201C\u201D\u2018\u2019]+$/g, '').trim();
const quoted = s => '"' + stripQ(s) + '"';

// Slide 3 ki yellow italic line: uncomfortable feel (id ke hisab se rotate)
const uncomfortable = [
  '— Some truths cost you peace.',
  '— You felt that. Don\'t pretend.',
  '— It hurts because it\'s true.',
  '— Now you can\'t unsee it.',
  '— You will remember this at 3 AM.',
  '— You already knew this.',
  '— Sit with that discomfort.',
  '— You read it twice, didn\'t you?',
  '— That one was meant for you.',
  '— Nobody warned you. We did.'
];
const seed = Number(q.id) || Math.floor(Math.random() * 1000);
const sign = uncomfortable[seed % uncomfortable.length];

// ---- Slide 1 hook: energetic. Bada, CAPS, akhri line yellow, aur "..." taake swipe karne ka dil kare ----
let hook = String(q.hook || '').trim().toUpperCase();
if (!/[.!?\u2026]$/.test(hook)) hook += '...';
const hookLines = wrap(hook, 14).split('\n');

// text = white hissa, extra = yellow hissa (extra me pehle blank lines taake wahi jagah par baithe)
// layout = height/width ka andaza; fixedY = text ki top y fix (do hisse align rakhne ke liye)
// pos: left = x 90, mid = center. ff = font width factor
const slides = [
  { text: hookLines.slice(0, -1).join('\n'),
    extra: '\n'.repeat(hookLines.length - 1) + hookLines[hookLines.length - 1],
    layout: hookLines.join('\n'), exb: 2, size: 96, font: 'impact', sign: '', pos: 'left', ff: 0.5, fixedY: true },
  { text: wrap(quoted(q.quote1), 24), extra: '', layout: wrap(quoted(q.quote1), 24), exb: 0,
    size: 46, font: 'palai', sign: '', pos: 'mid', ff: 0.50 },
  { text: wrap(quoted(q.quote2 || q.quote1), 24), extra: '', layout: wrap(quoted(q.quote2 || q.quote1), 24), exb: 0,
    size: 46, font: 'palai', sign: sign, pos: 'left', ff: 0.50 },
  { text: '', extra: wrap('Follow us for more', 13), layout: wrap('Follow us for more', 13), exb: 4,
    size: 110, font: 'inkfree', sign: '', pos: 'mid', ff: 0.50, fixedY: true }
];

// text ki height/position ka andaza (line ko text se door rakhne ke liye)
const LH = size => Math.round(size * 1.25) + 18;
slides.forEach(s => {
  const ls = s.layout.split('\n');
  s.textH = ls.length * LH(s.size);
  s.tt = (1350 - s.textH) / 2;
  s.tb = s.tt + s.textH;
  s.tw = Math.max(...ls.map(l => l.length)) * s.size * s.ff;
  s.xs = s.pos === 'mid' ? (1080 - s.tw) / 2 : 90;
});
const [s0, s1, s2, s3] = slides;

// ---- Seam heights (left/right edge same, taake swipe par line connected lage) ----
// y1: neeche (slide1 -> slide2), y2: upar (slide2 -> slide3), y3: neeche (slide3 -> slide4)
const lo = clamp(Math.max(s0.tb, s1.tb, s2.tb) + 80, 820, 960);
const y1 = rnd(lo, lo + 80);
const y2 = rnd(150, 280);
const y3lo = Math.min(Math.max(lo, s3.tb + 60), 1000);
const y3 = rnd(y3lo, y3lo + 60);
const cy = v => clamp(v, 100, 1100);

const P = [];
// Slide 1: hook ke neeche se start, neeche lehraati hui right edge y1 tak
{
  const sb = clamp(s0.tb + 55, 200, 1060);
  P.push([[90, sb], [300, sb + rnd(20, 60)], [560, (sb + y1) / 2 + rnd(0, 40)], [830, y1 + rnd(-30, 30)], [1080, y1]]);
}
// Slide 2: left-bottom se aaye -> text ke left se ghoomti hui UPAR -> text ke upar se guzar kar right edge y2 (upar)
{
  const xL = clamp(s1.xs - 70, 50, 130);
  const ttop = clamp(s1.tt - 80, 120, 480);
  P.push([
    [0, y1],
    [rnd(60, 110), cy(y1 - rnd(110, 170))],
    [xL, cy((y1 + ttop) / 2 + rnd(-30, 30))],
    [xL + rnd(0, 30), cy(ttop + rnd(40, 90))],
    [rnd(300, 380), cy(ttop - rnd(40, 100))],
    [rnd(640, 720), cy((ttop + y2) / 2 + rnd(-40, 40))],
    [900, cy(y2 + rnd(-30, 30))],
    [1080, y2]
  ]);
}
// Slide 3: upar se aaye -> text ke upar se -> right side se ghoomti hui NEECHE -> right edge y3
{
  const ttop = clamp(s2.tt - 90, 120, 470);
  const xR = clamp(90 + s2.tw + 90, 800, 1010);
  P.push([
    [0, y2],
    [rnd(220, 300), Math.min(ttop, y2 + rnd(40, 110))],
    [rnd(520, 620), Math.min(ttop, y2 + rnd(-20, 40))],
    [xR, ttop + rnd(0, 40)],
    [xR + rnd(-30, 20), (ttop + y3) / 2 + rnd(-30, 30)],
    [xR - rnd(30, 90), y3 - rnd(40, 90)],
    [1080, y3]
  ]);
}
// Slide 4: neeche se aaye -> S-curve -> left se ghoom kar upar -> text ki taraf arrow
{
  const tipX = clamp(s3.xs - 40, 150, 400);           // arrow ki nok: text ke left edge ke bilkul pass
  const tipY = s3.tt + Math.round(LH(s3.size) * 0.42); // pehli line ke beech ke barabar
  const xL = clamp(tipX - 120, 35, 90);
  const topY = Math.max(160, tipY - 150);
  P.push([
    [0, y3],
    [260, y3 + 25],
    [rnd(70, 110), y3 - rnd(90, 130)],
    [xL, (y3 + topY) / 2 + rnd(-30, 30)],
    [xL + rnd(0, 15), topY + rnd(0, 20)],
    [xL + (tipX - xL) * 0.5, topY - rnd(10, 40)],
    [tipX - 55, tipY - 45],     // nok se pehle wala point: isi se arrow ki direction banti hai
    [tipX, tipY]
  ]);
}
// pencil jaisa dusra halka stroke: thoda hilta hua (seam wale points nahi hilte)
const Pj = P.map(a => a.map(p => (p[0] <= 0 || p[0] >= 1080) ? p : [p[0] + rnd(-5, 5), p[1] + rnd(-5, 5)]));
const toStr = arr => arr.map(a => a.map(p => Math.round(p[0]) + ',' + Math.round(p[1])).join(';'));
const ptStr = toStr(P), ptStr2 = toStr(Pj);

const stamp = Date.now();
const dir = cfg.workDir;
const lines = [
  "$ErrorActionPreference='Stop'",
  "$ProgressPreference='SilentlyContinue'",
  "Add-Type -AssemblyName System.Drawing",
  "$d='" + dir + "'",
  "$r=\"$d\\run\"",
  "New-Item -ItemType Directory -Force $r | Out-Null",
  "Remove-Item \"$r\\*\" -Force -ErrorAction SilentlyContinue",
  "Set-Location $r",
  "'impact','palai','georgiai'|%{Copy-Item \"C:\\Windows\\Fonts\\$_.ttf\" \"$r\\$_.ttf\"}",
  "if(Test-Path 'C:\\Windows\\Fonts\\Inkfree.ttf'){ Copy-Item 'C:\\Windows\\Fonts\\Inkfree.ttf' \"$r\\inkfree.ttf\" } else { Copy-Item 'C:\\Windows\\Fonts\\segoescb.ttf' \"$r\\inkfree.ttf\" }",
  "$u=@(" + urls.map(u => "'" + u + "'").join(',') + ")",
  "$t=@(" + slides.map(s => "'" + (s.text ? b64(s.text) : '') + "'").join(',') + ")",
  "$ex=@(" + slides.map(s => "'" + (s.extra ? b64(s.extra) : '') + "'").join(',') + ")",
  "$exb=@(" + slides.map(s => s.exb).join(',') + ")",
  "$a=@(" + slides.map(s => "'" + (s.sign ? b64(s.sign) : '') + "'").join(',') + ")",
  "$s=@(" + slides.map(s => s.size).join(',') + ")",
  "$f=@(" + slides.map(s => "'" + s.font + "'").join(',') + ")",
  "$xp=@(" + slides.map(s => "'" + (s.pos === 'mid' ? '(w-text_w)/2' : '90') + "'").join(',') + ")",
  "$yp=@(" + slides.map(s => "'" + (s.fixedY ? Math.round(s.tt) : '(h-text_h)/2') + "'").join(',') + ")",
  "$pt=@(" + ptStr.map(x => "'" + x + "'").join(',') + ")",
  "$pt2=@(" + ptStr2.map(x => "'" + x + "'").join(',') + ")",
  "for($i=0;$i -lt 4;$i++){",
  "  $n=$i+1",
  "  Invoke-WebRequest -Uri $u[$i] -OutFile \"bg$n.jpg\"",
  "  $vf=\"scale=1080:1350:force_original_aspect_ratio=increase,crop=1080:1350,eq=brightness=-0.3,drawbox=x=0:y=0:w=iw:h=ih:color=black@0.3:t=fill,vignette=PI/4\"",
  "  $dt=\"fontfile=$($f[$i]).ttf:fontsize=$($s[$i]):line_spacing=18:shadowcolor=black@0.8:shadowx=4:shadowy=4:x=$($xp[$i]):y=$($yp[$i])\"",
  // white hissa
  "  if($t[$i] -ne ''){",
  "    [IO.File]::WriteAllBytes(\"$r\\t$n.txt\",[Convert]::FromBase64String($t[$i]))",
  "    $vf+=\",drawtext=$($dt):textfile=t$n.txt:fontcolor=white\"",
  "  }",
  // yellow bold hissa (borderw se bold jaisa)
  "  if($ex[$i] -ne ''){",
  "    [IO.File]::WriteAllBytes(\"$r\\e$n.txt\",[Convert]::FromBase64String($ex[$i]))",
  "    $vf+=\",drawtext=$($dt):textfile=e$n.txt:fontcolor=0xFFD400:borderw=$($exb[$i]):bordercolor=0xFFD400\"",
  "  }",
  // slide 3 ki yellow italic sign line (waisi hi)
  "  if($a[$i] -ne ''){",
  "    [IO.File]::WriteAllBytes(\"$r\\a$n.txt\",[Convert]::FromBase64String($a[$i]))",
  "    $vf+=\",drawtext=fontfile=georgiai.ttf:textfile=a$n.txt:fontcolor=0xFFD400:fontsize=36:x=90:y=h-250\"",
  "  }",
  "  & ffmpeg -y -loglevel error -i \"bg$n.jpg\" -vf $vf -frames:v 1 -q:v 2 \"base$n.jpg\"",
  "  if($LASTEXITCODE -ne 0){ throw \"ffmpeg fail slide $n\" }",
  // ---- pencil jaisi mota curvy line draw ----
  "  $img=[System.Drawing.Image]::FromFile(\"$r\\base$n.jpg\")",
  "  $g=[System.Drawing.Graphics]::FromImage($img)",
  "  $g.SmoothingMode='AntiAlias'",
  "  $pts=[System.Drawing.PointF[]]@($pt[$i].Split(';')|%{ $xy=$_.Split(','); New-Object System.Drawing.PointF([single]$xy[0],[single]$xy[1]) })",
  "  $pts2=[System.Drawing.PointF[]]@($pt2[$i].Split(';')|%{ $xy=$_.Split(','); New-Object System.Drawing.PointF([single]$xy[0],[single]$xy[1]) })",
  "  $pen=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(235,255,212,0),11)",
  "  $pen.StartCap='Round'; $pen.EndCap='Round'; $pen.LineJoin='Round'",
  "  $pen2=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(150,255,212,0),4)",
  "  $pen2.StartCap='Round'; $pen2.EndCap='Round'; $pen2.LineJoin='Round'",
  "  $g.DrawCurve($pen,$pts,0.6)",
  "  $g.DrawCurve($pen2,$pts2,0.6)",
  "  $br=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(255,255,212,0))",
  "  if($i -eq 0){ $g.FillEllipse($br,$pts[0].X-13,$pts[0].Y-13,26,26) }",
  // ---- akhri slide: arrow head (Follow us for more text ki taraf) ----
  "  if($i -eq 3){",
  "    $e=$pts[$pts.Length-1]; $q=$pts[$pts.Length-2]",
  "    $ang=[Math]::Atan2($e.Y-$q.Y,$e.X-$q.X)",
  "    foreach($da in 0.5,-0.5){",
  "      $ax=$e.X-65*[Math]::Cos($ang+$da); $ay=$e.Y-65*[Math]::Sin($ang+$da)",
  "      $g.DrawLine($pen,[single]$e.X,[single]$e.Y,[single]$ax,[single]$ay)",
  "    }",
  "  }",
  "  $enc=[System.Drawing.Imaging.ImageCodecInfo]::GetImageEncoders()|?{$_.MimeType -eq 'image/jpeg'}",
  "  $ep=New-Object System.Drawing.Imaging.EncoderParameters(1)",
  "  $ep.Param[0]=New-Object System.Drawing.Imaging.EncoderParameter([System.Drawing.Imaging.Encoder]::Quality,[long]95)",
  "  $img.Save(\"$r\\slide$n.jpg\",$enc,$ep)",
  "  $g.Dispose(); $img.Dispose(); $pen.Dispose(); $pen2.Dispose(); $br.Dispose()",
  "}",
  "if((Test-Path \"$d\\song.mp3\") -and ((Get-Item \"$d\\song.mp3\").Length -gt 10000)){ try { & ffmpeg -y -loglevel error -framerate 1/3.5 -i slide%d.jpg -i \"$d\\song.mp3\" -t 14 -vf format=yuv420p -r 30 -c:v libx264 -c:a aac -shortest preview.mp4 2>$null } catch {} }",
  "$h=@{Authorization='Bearer " + cfg.zernioKey + "';'Content-Type'='application/json'}",
  "$out=@()",
  "for($i=1;$i -le 4;$i++){",
  "  $body=(@{filename=\"c" + stamp + "_slide$i.jpg\";contentType='image/jpeg'}|ConvertTo-Json -Compress)",
  "  $p=Invoke-RestMethod -Method Post -Uri 'https://zernio.com/api/v1/media/presign' -Headers $h -Body $body",
  "  Invoke-RestMethod -Method Put -Uri $p.uploadUrl -InFile \"$r\\slide$i.jpg\" -ContentType 'image/jpeg' | Out-Null",
  "  $out+=$p.publicUrl",
  "}",
  "$res=(@{urls=$out}|ConvertTo-Json -Compress)",
  "Set-Content -Path \"$d\\result.txt\" -Value $res",
  "Write-Output $res"
];
const script = lines.join('\n');

// Script ko file me likhte hain (command length ki limit khatam)
const fs = require('fs');
fs.mkdirSync(dir, { recursive: true });
const ps1 = dir + '\\render.ps1';
fs.writeFileSync(ps1, script, 'utf8');

const command = 'powershell -NoProfile -ExecutionPolicy Bypass -File "' + ps1 + '"';
return [{ json: { command, scriptChars: script.length } }];

const fs = require('fs');
const path = require('path');

const res = $input.first().json;
const cfg = $('Config').first().json;
const q = $('Pick Quote').first().json;

// 1. Pehle stdout se try karo, na mile to result.txt se padho
let line = (res.stdout || '').split(/\r?\n/).reverse().find(l => l.trim().startsWith('{'));

if (!line) {
  const f = path.join(cfg.workDir, 'result.txt');
  if (!fs.existsSync(f)) {
    throw new Error('stdout khali hai aur result.txt bhi nahi mili. Execute Command chala hi nahi. stderr: ' + (res.stderr || ''));
  }
  const ageMin = (Date.now() - fs.statSync(f).mtimeMs) / 60000;
  if (ageMin > 10) {
    throw new Error('result.txt purani hai (' + Math.round(ageMin) + ' min). Is baar Execute Command ne script chalayi hi nahi.');
  }
  line = fs.readFileSync(f, 'utf8').replace(/^\uFEFF/, '').trim();
}

const urls = JSON.parse(line).urls;
if (!urls || urls.length < 4) throw new Error('4 image URLs nahi mile: ' + line);

const caption = q.caption || (q.hook + '\n\n' + q.quote1 + '\n\nFollow for more');
return [{ json: { body: {
  content: caption,
  mediaItems: urls.map(u => ({ url: u, type: 'image' })),
  platforms: [{ platform: 'instagram', accountId: cfg.zernioAccountId }],
  publishNow: true
} } }];

const fs = require('fs');
const path = require('path');

// 1. Folder setup (folder na ho to bana dega)
const workDir = $('Config').first().json.workDir || '/tmp';
fs.mkdirSync(workDir, { recursive: true });
const filePath = path.join(workDir, 'song.mp3');

// 2. Binary key dhoondo
const binaryItem = $input.first().binary;
if (!binaryItem) {
  throw new Error('Pichle node se koi binary (audio) data nahi mila!');
}
const binaryKey = Object.keys(binaryItem)[0];

// 3. Sahi tareeke se asli file buffer lo
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);

if (!buffer || buffer.length === 0) {
  throw new Error('Download Song ne 0 byte file di. Drive download me problem hai, Save Song me nahi.');
}

// 4. Save karo
fs.writeFileSync(filePath, buffer);

return [{
  json: {
    success: true,
    savedPath: filePath,
    sizeBytes: buffer.length
  }
}];
